import{_ as a,o as l,c as t,a6 as e}from"./chunks/framework.BlDtR6jM.js";const n="/Art_web_public/assets/image.CpMaPNOj.png",o="/Art_web_public/assets/image-1.NdcJ5n68.png",r="/Art_web_public/assets/image-2.LC9ePNjL.png",s="/Art_web_public/assets/image-3.BTHfatLF.png",c="/Art_web_public/assets/image-4.DZjAJD8S.png",h="/Art_web_public/assets/image-5.gCVrRaU0.png",q=JSON.parse('{"title":"空间切换（Space Switching）动画技术原理与操作","description":"","frontmatter":{"readingTime":"21 min read"},"headers":[],"relativePath":"全流程美术/动画/Space_Switching/空间切换原理与操作教程.md","filePath":"全流程美术/动画/Space_Switching/空间切换原理与操作教程.md"}'),u={name:"全流程美术/动画/Space_Switching/空间切换原理与操作教程.md"};function m(d,i,g,p,b,f){return l(),t("div",null,[...i[0]||(i[0]=[e('<h1 id="空间切换-space-switching-动画技术原理与操作" tabindex="-1">空间切换（Space Switching）动画技术原理与操作 <a class="header-anchor" href="#空间切换-space-switching-动画技术原理与操作" aria-label="Permalink to &quot;空间切换（Space Switching）动画技术原理与操作&quot;">​</a></h1><h2 id="什么是-space-switching" tabindex="-1">什么是 Space Switching？ <a class="header-anchor" href="#什么是-space-switching" aria-label="Permalink to &quot;什么是 Space Switching？&quot;">​</a></h2><p><strong>Space Switching</strong> 是一种动画控制技术，允许在多个参考空间之间动态切换控制器的“父级”，而不影响其世界空间的位置与旋转。<br> 但<strong>Space Switching</strong>不只是一个动画技术，更是一种绑定理念的转变。伴随这个理念，配合必要脚本工具，动画师将掌握一种轻量灵活的动画控制系统。</p><h2 id="为什么使用-space-switching" tabindex="-1">为什么使用 Space Switching？ <a class="header-anchor" href="#为什么使用-space-switching" aria-label="Permalink to &quot;为什么使用 Space Switching？&quot;">​</a></h2><p>传统 IK/FK 切换系统常常导致控制器臃肿、流程繁琐。而 Space Switching不受绑定系统预先设置的限制。灵活，轻量。</p><table tabindex="0"><thead><tr><th>对比点</th><th>传统 IK/FK 系统</th><th>Space Switching</th></tr></thead><tbody><tr><td>控制器数量</td><td>多，结构复杂</td><td>少，结构精简</td></tr><tr><td>切换方式</td><td>属性驱动 + 手动切换</td><td>动态约束 + 脚本辅助</td></tr><tr><td>灵活性</td><td>结构固定</td><td>动画师主导，按需调整</td></tr><tr><td>操作流程</td><td>绑定师预设 → 动画师使用</td><td>动画师即时决定控制方式</td></tr><tr><td>使用门槛</td><td>依赖绑定系统</td><td>脚本自动化简化操作</td></tr></tbody></table><h2 id="空间切换要点" tabindex="-1">空间切换要点 <a class="header-anchor" href="#空间切换要点" aria-label="Permalink to &quot;空间切换要点&quot;">​</a></h2><ul><li>标准流程：采样到代理（约束）→烘焙→在代理上编辑→反向约束驱动原控件→烘焙回写→清理</li><li>常规绑定下曲线多是“相对父级的偏移”，因此同一控制器的曲线并不直接对应“它在世界里做了什么”，读起来不直观</li><li>空间转换的目标是把编辑迁移到“世界空间的干净曲线”上：先采样出代理（定位器），在代理上编辑，再把结果回写为原控制器的相对偏移</li><li>并非只靠曲线：会配合约束参数（Maintain Offset、World Up Type）、动画图层权重、以及粒子/物理滞后等生成或调整运动</li><li>Aim Space（末端轨迹驱动旋转）：Root/Offset/Target 三定位器，Target的平移曲线决定链路旋转，显著降噪</li><li>两点枢轴道具：为重锤/剑等定义真实枢轴根与目标，两段流程处理空中主弧线与地面接触滚动</li><li>Aim 的 World Up Type优先用“Object Rotation Up”，取稳定参考的逐帧旋转，否则易滚转乱轴</li><li>捕获“路径”不要用 Point+Orient代替Parent；它们只分别取平移/旋转，不是路径综合</li><li>代理采样→在世界/Aim/两点枢轴空间编辑→反向约束回驱→烘焙回写→清理</li><li>图层权重与热键/脚本统一工作方式</li><li>性能与维护：减少三套融合（FK/IK/rig），避免复杂混合属性；保持选择集与 Picker 不失效</li><li>只用 FK 配合空间技巧的场景：武器/链路（Aim）、脊柱补间（近似 Spline IK）、道具空中主弧线</li><li>最小保留 IK 的场景：地面接触/脚种植、精确抓取/机械约束、硬体机器人步态</li><li>弧线主导的动作：手臂挥剑、武器/尾巴/耳朵的路径驱动（Aim Space、嵌入Aim串）。</li><li>脊柱补间：希望“用平移驱动旋转”的阶段，FK→Aim空间近似 Spline IK，Tween 更高效。</li></ul><h2 id="术语对照" tabindex="-1">术语对照 <a class="header-anchor" href="#术语对照" aria-label="Permalink to &quot;术语对照&quot;">​</a></h2><ul><li>COG（中枢/躯干控制）、Root（根）、COM（质心）</li></ul><h2 id="常用操作" tabindex="-1">常用操作 <a class="header-anchor" href="#常用操作" aria-label="Permalink to &quot;常用操作&quot;">​</a></h2><ul><li>将控件转换到世界空间编辑再回写 <ul><li>建定位器→点+朝向约束到控件（不保持偏移）</li><li>烘焙定位器→删除约束</li><li>定位器点+朝向约束驱动控件→在定位器上编辑</li><li>烘焙并删除定位器</li></ul></li><li>腾空期切换 IK 足到本地空间（相对COG） <ul><li>建定位器并父到COG→足控父约束驱动定位器→烘焙</li><li>定位器父约束驱动足控→编辑腾空段→烘焙</li></ul></li><li>统一重定向“路径+朝向” <ul><li>双定位器成父子→子采样Root并烘焙→子驱动Root</li><li>旋转父定位器改变前进方向→烘焙清理</li></ul></li><li>Aim 手腕/武器 <ul><li>Root/Offset/Target三定位器→Offset驱动手（父约束）</li><li>Target驱动Offset（Aim，World Up=Root旋转，保持偏移）</li><li>在Target曲线上编辑路径→烘焙清理</li></ul></li><li>两点枢轴（空中+接触双Pass） <ul><li>Pass1：枢轴根/目标定位器对齐并偏移→Offset父约束道具→目标对Offset Aim</li><li>Pass2：枢轴移至接触点→接触段删平移、做Z摆→烘焙清理</li></ul></li><li>从脚滑复原胶囊前进 <ul><li>定位器约束脚→取地面后滑段反向→清非前进轴</li><li>胶囊父约束到定位器→烘焙清理</li></ul></li></ul><h2 id="教程详细" tabindex="-1">教程详细 <a class="header-anchor" href="#教程详细" aria-label="Permalink to &quot;教程详细&quot;">​</a></h2><h3 id="_1-层级与约束-constraints-and-hierarchy" tabindex="-1">1 层级与约束 Constraints and Hierarchy <a class="header-anchor" href="#_1-层级与约束-constraints-and-hierarchy" aria-label="Permalink to &quot;1 层级与约束 Constraints and Hierarchy&quot;">​</a></h3><ul><li>层级（Parent/Child）：子物体随父物体求解，子上的键仅表现“相对偏移”</li><li>约束类型 <ul><li>父约束（Parent）：同时采样平移+旋转</li><li>点约束（Point）：仅平移</li><li>朝向约束（Orient）：仅旋转</li></ul></li><li>关键差异：Point+Orient ≠ Parent，二者是“分别取值”，而非“路径上的综合”</li><li>烘焙（Bake） <ul><li>将约束或层级导致的随动行为“投影”为关键帧曲线</li><li>子在父层级下烘焙通常得到“平坦键”（仅偏移），捕获世界运动应先脱离层级</li></ul></li></ul><h3 id="_2-世界空间转换-world-space-conversion" tabindex="-1">2 世界空间转换（World Space Conversion） <a class="header-anchor" href="#_2-世界空间转换-world-space-conversion" aria-label="Permalink to &quot;2 世界空间转换（World Space Conversion）&quot;">​</a></h3><ul><li>概述：把相对父级的动作转换为世界空间的真实运动</li><li>要点：定位器采样→烘焙→反向驱动→编辑世界曲线→回写</li><li>用途：清理大势、减少噪声、提高编辑效率</li></ul><h3 id="_3-rapid-iteration" tabindex="-1">3 Rapid Iteration <a class="header-anchor" href="#_3-rapid-iteration" aria-label="Permalink to &quot;3 Rapid Iteration&quot;">​</a></h3><ul><li>概述：以空间切换配方加速从blocking到细化的迭代</li><li>要点：世界采样→大势编辑→回写；图层与热键的协同</li><li>用途：快速试错与反馈驱动的动画流程</li></ul><h3 id="_4-offsetting-rotation" tabindex="-1">4 Offsetting Rotation <a class="header-anchor" href="#_4-offsetting-rotation" aria-label="Permalink to &quot;4 Offsetting Rotation&quot;">​</a></h3><ul><li>概述：通过相位与时间偏移让旋转更自然</li><li>要点：分节错位；世界到局部的映射关系；避免整链同帧触发</li><li>用途：次级运动的有机化</li></ul><h3 id="_5-manipulating-time" tabindex="-1">5 Manipulating Time <a class="header-anchor" href="#_5-manipulating-time" aria-label="Permalink to &quot;5 Manipulating Time&quot;">​</a></h3><ul><li>概述：以时间曲线重构运动节奏与物理感</li><li>要点：关键帧密度与插值；线性/加速/减速的选择</li><li>用途：提高节奏控制与物理一致性</li></ul><h3 id="_6-动画师的-mel-快速上手-将操作变成按钮-mel-for-animators" tabindex="-1">6 动画师的 MEL 快速上手（将操作变成按钮）Mel for Animators <a class="header-anchor" href="#_6-动画师的-mel-快速上手-将操作变成按钮-mel-for-animators" aria-label="Permalink to &quot;6 动画师的 MEL 快速上手（将操作变成按钮）Mel for Animators&quot;">​</a></h3><ul><li>用脚本编辑器“记录操作→清理→命名→做热键/货架按钮”</li></ul><h3 id="_7-ik-足部的世界-本地空间切换-animating-ik-in-world-and-local-spaces" tabindex="-1">7 IK 足部的世界/本地空间切换（Animating IK in World and Local Spaces） <a class="header-anchor" href="#_7-ik-足部的世界-本地空间切换-animating-ik-in-world-and-local-spaces" aria-label="Permalink to &quot;7 IK 足部的世界/本地空间切换（Animating IK in World and Local Spaces）&quot;">​</a></h3><ul><li>站立时，脚需要IK，足部在世界空间；跳起来时需要跟随身体局部空间。</li><li>一般方法是依懒绑定系统的IK,FK切换。但空间切换可以不依赖具体绑定系统。</li><li>操作 <ol><li>创建两个loc父约束到脚部IK</li><li>loc父给骨盆控制器，作为控制器的子物体</li><li>烘焙loc,然后删掉原父约束。反向再让loc去父约束IK柄</li></ol></li></ul><h3 id="_8-subverting-hierarchical-motion" tabindex="-1">8 Subverting Hierarchical Motion <a class="header-anchor" href="#_8-subverting-hierarchical-motion" aria-label="Permalink to &quot;8 Subverting Hierarchical Motion&quot;">​</a></h3><p>根骨骼的方向影响层级里所有的骨骼，游戏动画师都是在子骨骼上来制作动画<br> 如果要改变根骨骼的动画，但又不想影响整体子骨骼的动画<br> 这就需要<strong>对于根节点的每个直接子对象</strong>，创建一个loc 和前面同样操作，用父约束+烘焙+反向父约束来转换<br> 此时可以任意编辑父节点。编辑完成后选择<strong>对于根节点的每个直接子对象</strong>烘焙，删掉约束loc</p><h3 id="_9-动作采样与复用-motion-sampling-and-reuse" tabindex="-1">9 动作采样与复用（Motion Sampling and Reuse） <a class="header-anchor" href="#_9-动作采样与复用-motion-sampling-and-reuse" aria-label="Permalink to &quot;9 动作采样与复用（Motion Sampling and Reuse）&quot;">​</a></h3><p>在原地跑步改为位移跑步时，如果位移的幅度不是很精确，会产生了太空步的轻飘感。<br> 解决方法本质上是取后滑速度来重建角色前进位移幅度，让速度和距离匹配。<br> 首先还是老方法用loc去获取脚部的世界空间数据<br><img src="'+n+'" alt="alt text"><br> 脚部在世界空间的位移变化就取得了。比如X轴是前进方向，就在X轴上拟合截取一个近似值<br><img src="'+o+'" alt="alt text"><br> 反向曲线后，设置带偏移的循环。这个就是这个步迹下应该有的位移<br><img src="'+r+'" alt="alt text"><br> 但正式传递之前需要把其他轴向的废数据删掉<br><img src="'+s+'" alt="alt text"><br> 并且把其他轴向的值归零。清理非前进轴。<br><img src="'+c+'" alt="alt text"><br> 再到第一帧，用loc去约束root位移。最后烘焙并删除loc。就得到需要的准确根运动<br> 这样就把身体的某部分信息传递应用到另一部分。<br><strong>关键的关键</strong>是看中间过度loc最后去约束什么。</p><h3 id="_10-运算顺序切换-order-of-operation-switch" tabindex="-1">10 运算顺序切换（Order of Operation Switch） <a class="header-anchor" href="#_10-运算顺序切换-order-of-operation-switch" aria-label="Permalink to &quot;10 运算顺序切换（Order of Operation Switch）&quot;">​</a></h3><p>如果需要同时调整位移与旋转，需用父子结构的约束来做空间切换<br> 先用子loc获取位移并反约束回去。再用父loc做旋转<br><img src="'+h+'" alt="alt text"></p><ul><li>双定位器成父子层次</li><li>子定位器采样Root（Parent/Point+Orient约束）→烘焙。这一步子控制器获得位移值</li><li>子定位器驱动Root，父定位器统一旋转以改变行进方向</li><li>满意后烘焙并删除定位器</li></ul><h3 id="_11-rotation-distribution" tabindex="-1">11 Rotation Distribution <a class="header-anchor" href="#_11-rotation-distribution" aria-label="Permalink to &quot;11 Rotation Distribution&quot;">​</a></h3><ul><li>概述：将旋转合理分配到三段或多段链路</li><li>要点：权重/比率设定；保持体量与接触；避免单点过度</li><li>用途：更稳定的脊柱/尾巴/触手旋转</li></ul><h3 id="_12-prop-animation" tabindex="-1">12 Prop Animation <a class="header-anchor" href="#_12-prop-animation" aria-label="Permalink to &quot;12 Prop Animation&quot;">​</a></h3><ul><li>概述：以 Aim/两点枢轴等方法驱动道具（如剑）</li><li>要点：Root/Offset/Target；世界Up；接触段的清键与滚动</li><li>用途：更真实的武器与道具运动</li></ul><h3 id="_13-朝向空间-animating-in-aim-space" tabindex="-1">13 朝向空间 Animating in Aim Space <a class="header-anchor" href="#_13-朝向空间-animating-in-aim-space" aria-label="Permalink to &quot;13 朝向空间 Animating in Aim Space&quot;">​</a></h3><ul><li>理念：用“末端点的空间轨迹”驱动“关节旋转”，更易稳定与编辑</li><li>手腕/武器示例（剑尖） <ul><li>Root定位器作为“手的参考”，Target定位器放置在剑尖路径</li><li>用Offset定位器驱动手（父约束，保持偏移）</li><li>Aim设置要点 <ul><li>Maintain Offset：容许初始局部轴不完美对准</li><li>Aim Vector：指向目标的局部轴（如 +Y）</li><li>Up Vector：第二轴确定滚转（如 Z）</li><li>World Up Type：Object Rotation Up（取“Root”的逐帧旋转作为Up采样）</li></ul></li><li>在Target的平移曲线上做编辑，或用可编辑轨迹调整弧线</li></ul></li><li>关键优势：大幅降低“跟随链路”带来的抖动与曲线噪声</li><li>概述：用目标的空间轨迹直接驱动旋转</li><li>要点：三定位器（Root/Offset/Target）；Maintain Offset；Object Rotation Up</li><li>用途：稳态手腕/武器、降低链路噪声</li></ul><h3 id="_14-两点枢轴-two-point-pivots-用于道具" tabindex="-1">14 两点枢轴 （Two-Point Pivots）用于道具 <a class="header-anchor" href="#_14-两点枢轴-two-point-pivots-用于道具" aria-label="Permalink to &quot;14 两点枢轴 （Two-Point Pivots）用于道具&quot;">​</a></h3><ul><li>场景：重锤/枪等道具实际枢轴不在绑定骨的轴上</li><li>操作（Pass1：空中运动的主弧线） <ul><li>两定位器定义“枢轴根”和“枢轴目标”，子定位器为Offset</li><li>枢轴根/目标对齐道具（Point+Orient约束）→删除约束后手动偏移至理想枢轴</li><li>道具父约束到Offset（保持偏移）</li><li>以目标→Offset做Aim（World Up用枢轴根），在Offset旋转实现围绕新枢轴的运动</li></ul></li><li>操作（Pass2：地面接触的滚动与贴合） <ul><li>将枢轴重新定位至接触点，重新Aim并在接触段删除不必要的平移键</li><li>用Z轴微摆制造“圆头触地后滚动”的感觉</li></ul></li><li>效果：快速获得真实的受力与接触效果，不必从绑定骨曲线反推</li><li>概述：两点定义枢轴，快速得到真实接触/滚动</li><li>要点：枢轴根/目标/Offset；空中主弧线与接触再定位</li><li>用途：重道具/贴地滚动的可信表现</li></ul><h3 id="_15-caber-toss-working-in-depth-with-aim-space" tabindex="-1">15 Caber Toss - Working in-depth with Aim Space <a class="header-anchor" href="#_15-caber-toss-working-in-depth-with-aim-space" aria-label="Permalink to &quot;15 Caber Toss - Working in-depth with Aim Space&quot;">​</a></h3><ul><li>概述：深入用 Aim 处理大道具抛掷与落地</li><li>要点：多段目标；世界Up与重力感；接触段曲线整形</li><li>用途：高重量道具的物理可信度</li></ul><h3 id="_16-animating-quill-s-tail-embedded-aim-space-string" tabindex="-1">16 Animating Quill&#39;s Tail - Embedded Aim Space String <a class="header-anchor" href="#_16-animating-quill-s-tail-embedded-aim-space-string" aria-label="Permalink to &quot;16 Animating Quill&#39;s Tail - Embedded Aim Space String&quot;">​</a></h3><ul><li>问题：IK下链条旋转常同帧触发，观感“太IK”</li><li>解法：用Aim Space为FK链创建“末端轨迹”，分别在时间上错位编辑 <ul><li>先为每节骨建立Aim目标点（一致轴，如 +X）</li><li>分别移动各目标曲线的相位与幅度，制造上下游不同步</li></ul></li><li>效果：在保留“路径受控”的同时，让旋转时序更“有机”</li><li>用途：尾巴/鞭状体的自然响应</li></ul><h3 id="_17-building-ik-over-existing-animation" tabindex="-1">17 Building IK Over Existing Animation <a class="header-anchor" href="#_17-building-ik-over-existing-animation" aria-label="Permalink to &quot;17 Building IK Over Existing Animation&quot;">​</a></h3><ul><li>概述：在已有动画上叠加 IK 控制</li><li>要点：世界采样→转换→约束重挂→不破坏已有曲线</li><li>用途：后期加控与修正</li></ul><h3 id="_18-inverse-hierarchy-of-motion" tabindex="-1">18 Inverse Hierarchy of Motion <a class="header-anchor" href="#_18-inverse-hierarchy-of-motion" aria-label="Permalink to &quot;18 Inverse Hierarchy of Motion&quot;">​</a></h3><ul><li>概述：反向驱动层级以便编辑</li><li>要点：创建代理→反向约束→烘焙回写</li><li>用途：复杂层级的可控化</li></ul><h3 id="_19-building-fk-controls-over-ik" tabindex="-1">19 Building FK Controls Over IK <a class="header-anchor" href="#_19-building-fk-controls-over-ik" aria-label="Permalink to &quot;19 Building FK Controls Over IK&quot;">​</a></h3><ul><li>概述：在 IK 之上构建 FK 控制层</li><li>要点：缓冲与父子；权重切换；曲线保护</li><li>用途：姿势阶段与补间阶段的互补</li></ul><h3 id="_20-organic-offsetting-and-changing-the-way-time-solves" tabindex="-1">20 Organic Offsetting and Changing the way Time Solves <a class="header-anchor" href="#_20-organic-offsetting-and-changing-the-way-time-solves" aria-label="Permalink to &quot;20 Organic Offsetting and Changing the way Time Solves&quot;">​</a></h3><ul><li>概述：改变时间求解方式并做有机错位</li><li>要点：分节相位；目标曲线驱动旋转；避免“太IK”</li><li>用途：更自然的链路动态</li></ul><h3 id="_21-animating-with-particle-physics" tabindex="-1">21 Animating with Particle Physics <a class="header-anchor" href="#_21-animating-with-particle-physics" aria-label="Permalink to &quot;21 Animating with Particle Physics&quot;">​</a></h3><ul><li>概述：用粒子滞后/弹簧特性生成叠加运动</li><li>要点：Emitter/Goal 设置；目标约束烘焙；参数调优（僵硬度/滞后）</li><li>用途：自动化耳朵/背包/衣摆等</li></ul><h3 id="_22-center-of-mass-create" tabindex="-1">22 Center of Mass - Create <a class="header-anchor" href="#_22-center-of-mass-create" aria-label="Permalink to &quot;22 Center of Mass - Create&quot;">​</a></h3><ul><li>概述：创建并可视化角色质心（COM）</li><li>要点：依据身体部位权重做 Point 约束；可投影到地面根</li><li>用途：以数据检验平衡与物理轨迹</li></ul><h3 id="_23-center-of-mass-use-as-a-control-in-your-animation-rig" tabindex="-1">23 Center of Mass - Use as a Control in your Animation Rig <a class="header-anchor" href="#_23-center-of-mass-use-as-a-control-in-your-animation-rig" aria-label="Permalink to &quot;23 Center of Mass - Use as a Control in your Animation Rig&quot;">​</a></h3><ul><li>概述：把 COM 作为绑定控制以稳定整体</li><li>要点：子定位器记录偏移；反向约束由 COM 驱动；曲线清理</li><li>用途：去除“轻飘/木偶感”，保持稳态</li></ul><h3 id="_24-automation-animating-quill-s-ears" tabindex="-1">24 Automation - Animating Quill&#39;s Ears <a class="header-anchor" href="#_24-automation-animating-quill-s-ears" aria-label="Permalink to &quot;24 Automation - Animating Quill&#39;s Ears&quot;">​</a></h3><ul><li>概述：自动化耳朵次级运动</li><li>要点：两耳 Aim→平均定位器→粒子滞后→耳尖世界旋转延迟</li><li>用途：90% 以上自动生成，一致性强</li></ul><h3 id="_25-animating-quill-s-spine-works-for-baqir-too" tabindex="-1">25 Animating Quill&#39;s Spine (Works for Baqir too) <a class="header-anchor" href="#_25-animating-quill-s-spine-works-for-baqir-too" aria-label="Permalink to &quot;25 Animating Quill&#39;s Spine (Works for Baqir too)&quot;">​</a></h3><ul><li>概述：姿势用 FK，补间用 Aim 空间近似 Spline IK</li><li>要点：代理世界→层级更新→烘焙回写→逐段 Aim</li><li>用途：以平移驱动旋转，Tween 更高效</li></ul><h3 id="_26-automation-baqir-s-backpack" tabindex="-1">26 Automation - Baqir&#39;s Backpack <a class="header-anchor" href="#_26-automation-baqir-s-backpack" aria-label="Permalink to &quot;26 Automation - Baqir&#39;s Backpack&quot;">​</a></h3><ul><li>概述：综合 Aim 与粒子自动化背包与卷轴</li><li>要点：整体物理→目标点 Aim→分组批处理→烘焙与图层权重</li><li>用途：风格统一与高效批量</li></ul><h3 id="_27-automation-creating-a-snake-slither-from-one-rotation-curve" tabindex="-1">27 Automation - Creating a Snake Slither from One Rotation Curve <a class="header-anchor" href="#_27-automation-creating-a-snake-slither-from-one-rotation-curve" aria-label="Permalink to &quot;27 Automation - Creating a Snake Slither from One Rotation Curve&quot;">​</a></h3><ul><li>概述：用一条旋转曲线生成整条蛇的波动</li><li>要点：相位偏移与幅度渐变；逐节延迟；路径约束配合</li><li>用途：程序化长链体运动</li></ul><h3 id="_28-automation-generating-butterfly-motion-from-a-wing-flap-and-position-in-space" tabindex="-1">28 Automation - Generating Butterfly Motion from a Wing Flap and Position in Space <a class="header-anchor" href="#_28-automation-generating-butterfly-motion-from-a-wing-flap-and-position-in-space" aria-label="Permalink to &quot;28 Automation - Generating Butterfly Motion from a Wing Flap and Position in Space&quot;">​</a></h3><ul><li>概述：由翼拍与空间位置生成蝴蝶飞行</li><li>要点：翼拍驱动体姿；位移映射俯仰/滚转；Aim 与粒子结合</li><li>用途：快速生成可信的飞行动作</li></ul><h3 id="_29-automation-generating-a-walking-robot-from-basic-foot-motion" tabindex="-1">29 Automation - Generating a Walking Robot From Basic Foot Motion <a class="header-anchor" href="#_29-automation-generating-a-walking-robot-from-basic-foot-motion" aria-label="Permalink to &quot;29 Automation - Generating a Walking Robot From Basic Foot Motion&quot;">​</a></h3><ul><li>概述：用基本足部运动自动生成机器人步行</li><li>要点：足部相位与接触；根位移采样；上身分配旋转</li><li>用途：程序化硬体步态</li></ul><h3 id="_30-animating-baqir-using-space-switching-in-a-production-animation" tabindex="-1">30 Animating Baqir - Using Space Switching in a Production Animation <a class="header-anchor" href="#_30-animating-baqir-using-space-switching-in-a-production-animation" aria-label="Permalink to &quot;30 Animating Baqir - Using Space Switching in a Production Animation&quot;">​</a></h3><ul><li>概述：生产案例整合各空间切换技巧</li><li>要点：计划→采样→Aim/两点→粒子→回写与清理</li><li>用途：端到端的工作流示范</li></ul><h3 id="bonus-lecture-1-group-animation-via-scale" tabindex="-1">Bonus Lecture #1 Group Animation Via Scale <a class="header-anchor" href="#bonus-lecture-1-group-animation-via-scale" aria-label="Permalink to &quot;Bonus Lecture #1 Group Animation Via Scale&quot;">​</a></h3><ul><li>概述：用 Scale 协调群体/组动画</li><li>要点：父组缩放影响子级；曲线联动；烘焙策略</li><li>用途：群体动作的一致调控</li></ul><h3 id="bonus-lecture-3-aim-space-string-without-a-hierarchy-change" tabindex="-1">Bonus Lecture #3 Aim Space String (Without a hierarchy change) <a class="header-anchor" href="#bonus-lecture-3-aim-space-string-without-a-hierarchy-change" aria-label="Permalink to &quot;Bonus Lecture #3 Aim Space String (Without a hierarchy change)&quot;">​</a></h3><ul><li>概述：不改层级实现 Aim Space 串</li><li>要点：仅靠约束与代理；逐节目标；回写不破坏原层级</li><li>用途：保守环境下的安全改造</li></ul><h3 id="bonus-lecture-4-multi-point-ground-contacts" tabindex="-1">Bonus Lecture #4 Multi-point Ground Contacts <a class="header-anchor" href="#bonus-lecture-4-multi-point-ground-contacts" aria-label="Permalink to &quot;Bonus Lecture #4 Multi-point Ground Contacts&quot;">​</a></h3><ul><li>概述：多接触点的地面约束与切换</li><li>要点：分接触阶段约束；权重平衡；接触段曲线整形</li><li>用途：复杂支撑的稳定性</li></ul><h3 id="animation-sherpa-2066-mp4-srt" tabindex="-1">Animation Sherpa[2066, Mp4].srt <a class="header-anchor" href="#animation-sherpa-2066-mp4-srt" aria-label="Permalink to &quot;Animation Sherpa[2066, Mp4].srt&quot;">​</a></h3><ul><li>概述：系列概览/开场对白与主旨</li><li>要点：空间切换思想、效率与风格统一的重要性</li><li>用途：理解系列整体目标与方法论</li></ul><h2 id="💻-推荐脚本工具与资源" tabindex="-1">💻 推荐脚本工具与资源 <a class="header-anchor" href="#💻-推荐脚本工具与资源" aria-label="Permalink to &quot;💻 推荐脚本工具与资源&quot;">​</a></h2><ul><li>🎓 <a href="https://www.animationsherpa.com/courses/space-switching" target="_blank" rel="noreferrer">Animation Sherpa - Space Switching 教程</a></li><li>🔧 <a href="https://pavelbarnev.gumroad.com/l/OverRigBasic" target="_blank" rel="noreferrer">OverRig - Pavel Barnev 开发工具集</a></li><li>▶️ <a href="https://www.youtube.com/watch?v=YlxmJX4KJm8" target="_blank" rel="noreferrer">YouTube - OverRig 使用演示视频</a></li><li>🎓<a href="http://forum.mgear-framework.com/t/space-switching-animation-tool/1626" target="_blank" rel="noreferrer">Space Switching Animation Tool-mGear</a></li><li><a href="https://github.com/mgear-dev/mgear_dist" target="_blank" rel="noreferrer">github_mgear_dist</a></li><li><a href="https://www.mgear-framework.com/" target="_blank" rel="noreferrer">mGear &amp; ueGear Framework</a></li></ul>',84)])])}const k=a(u,[["render",m]]);export{q as __pageData,k as default};
